import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { motion } from 'framer-motion';
import { Clock, CheckCircle, AlertTriangle, XCircle, FileText, Link as LinkIcon, UploadCloud } from 'lucide-react';
import axios from 'axios';

const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:4000/api';

export default function Dashboard() {
  const [sessions, setSessions] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    axios.get(`${API_URL}/verification-history`)
      .then(res => setSessions(res.data.sessions))
      .catch(err => console.error(err))
      .finally(() => setLoading(false));
  }, []);

  const getTypeIcon = (type) => {
    switch (type) {
      case 'resume': return <FileText size={18} />;
      case 'drive-link': return <LinkIcon size={18} />;
      default: return <UploadCloud size={18} />;
    }
  };

  if (loading) return <div style={{ textAlign: 'center', marginTop: '40px' }}>Loading...</div>;

  return (
    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
      <h2 style={{ fontSize: '2rem', marginBottom: '24px', display: 'flex', alignItems: 'center', gap: '12px' }}>
        <Clock /> Verification History
      </h2>

      <div style={{ display: 'grid', gap: '16px' }}>
        {sessions.map(session => (
          <Link key={session.sessionId} to={`/session/${session.sessionId}`}>
            <motion.div 
              whileHover={{ x: 5 }}
              className="glass-panel" 
              style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '16px 24px', cursor: 'pointer' }}
            >
              <div>
                <div style={{ display: 'flex', alignItems: 'center', gap: '12px', marginBottom: '8px' }}>
                  <span style={{ color: 'var(--accent-primary)' }}>{getTypeIcon(session.type)}</span>
                  <span style={{ fontWeight: '600', textTransform: 'capitalize' }}>
                    {session.type.replace('-', ' ')}
                  </span>
                  <span style={{ color: 'var(--text-secondary)', fontSize: '0.875rem' }}>
                    {new Date(session.timestamp).toLocaleString()}
                  </span>
                </div>
                {session.candidateName && (
                  <div style={{ color: 'var(--text-secondary)', fontSize: '0.875rem' }}>
                    Candidate: <strong style={{ color: 'var(--text-primary)' }}>{session.candidateName}</strong>
                  </div>
                )}
              </div>

              <div style={{ display: 'flex', gap: '16px', fontSize: '0.875rem' }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '4px', color: 'var(--status-real)' }}>
                  <CheckCircle size={16} /> {session.summary.REAL || 0}
                </div>
                <div style={{ display: 'flex', alignItems: 'center', gap: '4px', color: 'var(--status-suspicious)' }}>
                  <AlertTriangle size={16} /> {session.summary.SUSPICIOUS || 0}
                </div>
                <div style={{ display: 'flex', alignItems: 'center', gap: '4px', color: 'var(--status-fake)' }}>
                  <XCircle size={16} /> {session.summary.FAKE || 0}
                </div>
              </div>
            </motion.div>
          </Link>
        ))}

        {sessions.length === 0 && (
          <div style={{ textAlign: 'center', color: 'var(--text-secondary)', padding: '40px' }}>
            No verifications yet.
          </div>
        )}
      </div>
    </motion.div>
  );
}
